const query = $input.first().json.query || {};
const mode = query['hub.mode'] || '';
const token = query['hub.verify_token'] || '';
const challenge = query['hub.challenge'] || '';
const baseUrl = ($env.VOICEAI_BASE_URL || 'http://voiceai-server:3001').replace(/\/+$/, '');

if (mode === 'subscribe' && token) {
  if ($env.META_VERIFY_TOKEN && token === $env.META_VERIFY_TOKEN) {
    return [{ json: { ok: true, statusCode: 200, challenge: String(challenge) } }];
  }
  try {
    const url = `${baseUrl}/api/whatsapp/meta-webhook-verify?hub.mode=${encodeURIComponent(mode)}&hub.verify_token=${encodeURIComponent(token)}&hub.challenge=${encodeURIComponent(challenge)}`;
    const res = await fetch(url);
    if (res.ok) {
      const text = await res.text();
      return [{ json: { ok: true, statusCode: 200, challenge: text || String(challenge) } }];
    }
  } catch {}
}
return [{ json: { ok: false, statusCode: 403, challenge: 'Forbidden' } }];

const body = $input.first().json.body || $input.first().json;
const baseUrl = ($env.VOICEAI_BASE_URL || 'http://voiceai-server:3001').replace(/\/+$/, '');
const defaultClinicId = $env.VOICEAI_CLINIC_ID || 'auto';
const secret = $env.VOICEAI_N8N_SECRET || '';

const res = await fetch(`${baseUrl}/api/whatsapp/n8n-webhook/${encodeURIComponent(defaultClinicId)}`, {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    ...(secret ? { 'X-Webhook-Secret': secret } : {})
  },
  body: JSON.stringify(body)
});
const data = await res.json().catch(() => ({}));
return [{ json: { status: res.status, response: data } }];
